import importlib
import inspect
import sys
import time
from functools import wraps


from robot.libraries.BuiltIn import BuiltIn, RobotNotRunningError


def _get_file_name(function):
    if function.__closure__ is not None:
        function = function.__closure__[0].cell_contents
    if inspect.isfunction(function) or inspect.ismethod(function):
        return inspect.getfile(function).split("/")[-1].strip(".py")


def get_module_name(function):
    module_file = _get_file_name(function)
    imported_libs = BuiltIn().get_library_instance(all=True)
    for lib, lib_path in imported_libs.items():
        if module_file.lower() in str(lib_path).lower():
            return lib
    BuiltIn().import_library(inspect.getabsfile(function), "WITH NAME", module_file)
    return module_file


def robot_kw(function):
    @wraps(function)
    def logger(*args, **kwargs):
        if not hasattr(function, "logged_kw"):
            setattr(function, "logged_kw", True)
            arguments = [arg for arg in args]
            key_args = [
                "{}=${{{}}}".format(kwarg, _project_robot_var_type(function.__name__, kwarg, value)) if not isinstance(
                    value, str) else "{}={}".format(kwarg, value) for kwarg, value in kwargs.items()]
            arguments.extend(key_args)
            func = ".".join([get_module_name(function), function.__name__])
            try:
                return BuiltIn().run_keyword(func, *arguments)
            except RobotNotRunningError:
                delattr(function, "logged_kw")
                return function(*args, **kwargs)
        else:
            delattr(function, "logged_kw")
            return function(*args, **kwargs)

    return logger


def robot_logger(msg, log_level="INFO", log_to_console=True):
    now = time.strftime("%H:%M:%S")
    if log_level.upper() == "INFO":
        BuiltIn().log("[ {} ] {} - {}".format(log_level.upper(), now, msg), level=log_level.upper(),
                      console=log_to_console)
    elif log_level.upper() == "WARN" or log_level.upper() == "ERROR":
        BuiltIn().log("{} - {}".format(now, msg), level=log_level.upper(), console=False)


def run_keyword_if_execution_failed(keyword, *args):
    """ Function Check if any exception occurred during
        execution of current Robot Keyword and
        run given keyword with passed arguments
        if any exception is visible"""
    if sys.exc_info()[1] is not None:
        BuiltIn().run_keyword(keyword, *args)


def wait_until_kw_succeeds(retry, retry_interval, function, *args, **kwargs):
    arguments = [arg for arg in args]
    key_args = [
        "{}=${{{}}}".format(kwarg, _project_robot_var_type(function.__name__, kwarg, value)) if not isinstance(
            value, str) else "{}={}".format(kwarg, value) for kwarg, value in kwargs.items()]
    arguments.extend(key_args)
    func = ".".join([get_module_name(function), function.__name__])
    return BuiltIn().wait_until_keyword_succeeds(retry, retry_interval, func, *arguments)


def robot_var(variable_name, default_value=None):
    return BuiltIn().get_variable_value("${{{}}}".format(variable_name), default_value)


def set_robot_test_variable(variable_name, value):
    BuiltIn().set_test_variable("${{{}}}".format(variable_name), value)


def set_robot_suite_variable(variable_name, value):
    BuiltIn().set_suite_variable("${{{}}}".format(variable_name), value)


def _project_robot_var_type(function_name, arg_name, value):
    temp_arg_name = "{}_{}".format(function_name, arg_name)
    set_robot_test_variable(temp_arg_name, value)
    return temp_arg_name


def robot_variable_exist(variable_name):
    try:
        BuiltIn().variable_should_exist("${{{}}}".format(variable_name))
        return True
    except AssertionError:
        return False


def run_kw(keyword_name, *args, **kwargs):
    arguments = [arg for arg in args]
    key_args = [
        "{}=${{{}}}".format(kwarg, _project_robot_var_type(keyword_name, kwarg, value)) if not isinstance(
            value, str) else "{}={}".format(kwarg, value) for kwarg, value in kwargs.items()]
    arguments.extend(key_args)
    return BuiltIn().run_keyword(keyword_name, *arguments)


def run_kw_and_ignore_error(keyword_name, return_error=False, *args, **kwargs):
    arguments = [arg for arg in args]
    key_args = [
        "{}=${{{}}}".format(kwarg, _project_robot_var_type(keyword_name, kwarg, value)) if not isinstance(
            value, str) else "{}={}".format(kwarg, value) for kwarg, value in kwargs.items()]
    arguments.extend(key_args)
    result, error = BuiltIn().run_keyword_and_ignore_error(keyword_name, *arguments)
    if return_error:
        return result, error
    return result


def run_method_and_ignore_error(method_name, return_error=False, *args, **kwargs):
    importlib.import_module(_get_file_name(method_name), method_name.__name__)
    func = getattr(sys.modules[_get_file_name(method_name)], method_name.__name__)
    try:
        func(*args, **kwargs)
        return "PASS"
    except Exception as error:
        if return_error:
            return "FAIL", error
        return "FAIL"
